{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.Zilo_inventory_report as WITH inv_sent AS ( SELECT CASE WHEN CONTAINS(UPPER(TRIM(factsss.sku)), \'_\') THEN SPLIT_PART(UPPER(TRIM(factsss.sku)), \'_\', 1) || \'-\' || SPLIT_PART(UPPER(TRIM(factsss.sku)), \'_\', -1) ELSE UPPER(TRIM(factsss.sku)) END AS sku, COALESCE( TO_DATE(sheet.SLOT_DATE, \'DD/MM/YYYY\'), TO_DATE(sheet.ORDER_DATE, \'DD/MM/YYYY\'), factsss.ORDER_DATE ) AS inward_date, SUM(factsss.SUBORDER_QUANTITY) AS qty_sent FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate AS factsss LEFT JOIN snitch_db.maplemonk.gs_mpforwards_sheet1 AS sheet ON factsss.order_id = sheet.SO_NUMBER AND sheet.MARKETPLACE = \'ZILO\' WHERE factsss.MARKETPLACE_MAPPED = \'ZILO\' AND factsss.SALE_ORDER_ITEM_STATUS NOT IN (\'CANCELLED\', \'UNFULFILLABLE\') GROUP BY 1, 2 ), pullback AS ( SELECT (SPLIT_PART(UPPER(TRIM(SKU)), \'-\', 1) || \'-\' || SPLIT_PART(UPPER(TRIM(SKU)), \'-\', 2) || \'-\' || SPLIT_PART(UPPER(TRIM(SKU)), \'-\', ARRAY_SIZE(SPLIT(UPPER(TRIM(SKU)), \'-\')))) AS sku, TO_DATE(DATE, \'DD-MM-YYYY\') AS outward_date, SUM(QTY::INT) AS pullback_inventory FROM snitch_db.maplemonk.S3_ZILO_PULLBACK GROUP BY 1, 2 ), min_dates AS ( SELECT sku, MIN(inward_date) AS first_inward_date FROM inv_sent GROUP BY 1 ), date_expanded AS ( SELECT m.sku, DATEADD(DAY, s.seq, m.first_inward_date) AS generated_date FROM min_dates m, LATERAL ( SELECT SEQ4() AS seq FROM TABLE(GENERATOR(ROWCOUNT => 10000)) ) s WHERE DATEADD(DAY, s.seq, m.first_inward_date) <= CURRENT_DATE() + 1 ), main_data AS ( SELECT sku, generated_date AS date FROM date_expanded ), sales AS ( SELECT sku, order_date, SUM(total_quantity) AS sales_qty, SUM(return_quantity) AS ret_qty FROM snitch_db.maplemonk.Zilo_fact_item GROUP BY 1, 2 ), base_data AS ( SELECT sku, date, first_inward_date, SUM(qty_sent) AS qty_sent, SUM(sales_qty) AS sales_qty, SUM(ret_qty) AS ret_qty, SUM(pullback_inventory) AS pullback_inventory FROM ( SELECT COALESCE(a.sku, c.sku) AS sku, COALESCE(a.date, e.first_inward_date) AS date, COALESCE(b.qty_sent, 0) AS qty_sent, COALESCE(c.sales_qty, 0) AS sales_qty, COALESCE(c.ret_qty, 0) AS ret_qty, COALESCE(k.pullback_inventory, 0) AS pullback_inventory, e.first_inward_date FROM main_data a LEFT JOIN inv_sent b ON a.date = b.inward_date AND a.sku = b.sku FULL OUTER JOIN sales c ON a.date = c.order_date AND a.sku = c.sku LEFT JOIN pullback k ON a.date = k.outward_date AND a.sku = k.sku LEFT JOIN min_dates e ON COALESCE(a.sku, c.sku) = e.sku ) GROUP BY 1, 2, 3 ), ordered_data AS ( SELECT sku, date, qty_sent, sales_qty, ret_qty, pullback_inventory, first_inward_date FROM base_data ), initial_rows AS ( SELECT sku, date, qty_sent, sales_qty, ret_qty, pullback_inventory, first_inward_date, CAST(0 AS NUMBER(38,0)) AS closing_inventory, CAST(qty_sent AS NUMBER(38,0)) AS opening_inventory, CAST((qty_sent - sales_qty + ret_qty - pullback_inventory) AS NUMBER(38,0)) AS closing_inventory_new FROM ordered_data WHERE (sku, date) IN ( SELECT sku, MIN(date) FROM ordered_data GROUP BY sku ) ), recursive_inventory AS ( SELECT * FROM initial_rows UNION ALL SELECT curr.sku, curr.date, curr.qty_sent, curr.sales_qty, curr.ret_qty, curr.pullback_inventory, curr.first_inward_date, prev.closing_inventory_new AS closing_inventory, (prev.closing_inventory_new + curr.qty_sent)::NUMBER(38,0) AS opening_inventory, (prev.closing_inventory_new + curr.qty_sent - curr.sales_qty + curr.ret_qty - curr.pullback_inventory)::NUMBER(38,0) AS closing_inventory_new FROM recursive_inventory prev JOIN ordered_data curr ON curr.sku = prev.sku AND curr.date = DATEADD(DAY, 1, prev.date) ), with_sku_group AS ( SELECT *, REGEXP_REPLACE(sku, \'-[^-]*$\', \'\') AS sku_group, SPLIT_PART(sku, \'-\', ARRAY_SIZE(SPLIT(sku, \'-\'))) AS size FROM recursive_inventory ), latest_metafields AS ( SELECT sku_group, category, title, material_new, print_design, fit, sleeve_type, collar_new FROM snitch_db.maplemonk.metafields_data QUALIFY ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY status DESC) = 1 ), fallback_metafields AS ( SELECT SKU_GROUP, CATEGORY, TITLE, MATERIAL_NEW, PRINT_DESIGN, FIT, SLEEVE_TYPE, COLLAR_NEW FROM snitch_db.maplemonk.GS_MP_SKU_META_SHEET1 QUALIFY ROW_NUMBER() OVER(PARTITION BY SKU_GROUP ORDER BY SKU_GROUP) = 1 ), mp_categories AS ( SELECT DISTINCT REGEXP_REPLACE(SKU, \'-[^-]*$\', \'\') AS sku_group, ANY_VALUE(CATEGORY) AS category FROM snitch_db.maplemonk.LOGIC_FINAL_ITEM_MASTER WHERE SKU LIKE \'MP%\' GROUP BY 1 ) SELECT w.sku, w.sku_group, w.size, w.date, w.qty_sent, w.sales_qty, w.ret_qty, w.pullback_inventory, w.first_inward_date, w.opening_inventory, w.closing_inventory_new AS closing_inventory, INITCAP(COALESCE(mpc.category, m.category, fb.CATEGORY)) AS category, COALESCE(m.title, fb.TITLE) AS title, COALESCE(m.material_new, fb.MATERIAL_NEW) AS material_new, COALESCE(m.print_design, fb.PRINT_DESIGN) AS print_design, COALESCE(m.fit, fb.FIT) AS fit, COALESCE(m.sleeve_type, fb.SLEEVE_TYPE) AS sleeve_type, COALESCE(m.collar_new, fb.COLLAR_NEW) AS collar_new FROM with_sku_group w LEFT JOIN latest_metafields m ON w.sku_group = m.sku_group LEFT JOIN mp_categories mpc ON w.sku_group = mpc.sku_group LEFT JOIN fallback_metafields fb ON w.sku_group = fb.SKU_GROUP ORDER BY w.sku, w.date;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            